// Parse and validate approval request
const input = $input.first().json;
const body = input.body || input;

// Validate required fields
if (!body.type) {
  throw new Error('Missing required field: type');
}
if (!body.requester) {
  throw new Error('Missing required field: requester');
}

// Create approval request
const request = {
  id: `apr_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
  type: body.type,
  requester: {
    id: body.requester.id || body.requester,
    email: body.requester.email || body.requesterEmail,
    name: body.requester.name || body.requesterName
  },
  subject: body.subject || `${body.type} Request`,
  description: body.description || '',
  data: body.data || {},
  priority: body.priority || 'normal',
  amount: body.amount || null,
  deadline: body.deadline || null,
  status: 'pending',
  createdAt: new Date().toISOString(),
  approvals: [],
  currentLevel: 1,
  escalationCount: 0
};

return [{ json: request }];

// Determine approvers based on request type and amount
const request = $input.first().json;

// Approval rules (in production, load from database)
const approvalRules = {
  'expense': [
    { level: 1, threshold: 1000, approvers: ['manager@example.com'] },
    { level: 2, threshold: 5000, approvers: ['director@example.com'] },
    { level: 3, threshold: Infinity, approvers: ['cfo@example.com'] }
  ],
  'leave': [
    { level: 1, threshold: 3, approvers: ['manager@example.com'] },
    { level: 2, threshold: Infinity, approvers: ['hr@example.com'] }
  ],
  'purchase': [
    { level: 1, threshold: 500, approvers: ['team-lead@example.com'] },
    { level: 2, threshold: 2000, approvers: ['manager@example.com'] },
    { level: 3, threshold: 10000, approvers: ['director@example.com'] },
    { level: 4, threshold: Infinity, approvers: ['cfo@example.com'] }
  ],
  'default': [
    { level: 1, threshold: Infinity, approvers: ['admin@example.com'] }
  ]
};

// Get applicable rules
const rules = approvalRules[request.type] || approvalRules['default'];
const amount = request.amount || 0;

// Determine required approval levels
const requiredLevels = rules.filter(r => amount <= r.threshold || r.threshold === Infinity)
  .slice(0, rules.findIndex(r => amount <= r.threshold) + 1 || rules.length);

// Get current level approvers
const currentRule = requiredLevels.find(r => r.level === request.currentLevel) || requiredLevels[0];

// Check for delegation/out-of-office (simulated)
const delegations = {
  'manager@example.com': { delegateTo: 'deputy-manager@example.com', until: '2025-12-31' }
};

const finalApprovers = currentRule.approvers.map(approver => {
  const delegation = delegations[approver];
  if (delegation && new Date(delegation.until) > new Date()) {
    return delegation.delegateTo;
  }
  return approver;
});

return [{
  json: {
    ...request,
    approvalChain: requiredLevels,
    currentApprovers: finalApprovers,
    totalLevels: requiredLevels.length,
    timeoutMinutes: request.priority === 'urgent' ? 60 : 1440 // 1 hour or 24 hours
  }
}];

// Store approval request and prepare notifications
const request = $input.first().json;
const staticData = $workflow.staticData;

// Initialize storage
if (!staticData.approvals) {
  staticData.approvals = {};
}

// Store request
staticData.approvals[request.id] = {
  ...request,
  expiresAt: new Date(Date.now() + request.timeoutMinutes * 60000).toISOString()
};

// Generate approval links
const baseUrl = 'http://localhost:5678/webhook';
const approvalLinks = request.currentApprovers.map(approver => ({
  approver,
  approveUrl: `${baseUrl}/approval/respond?id=${request.id}&action=approve&approver=${encodeURIComponent(approver)}`,
  rejectUrl: `${baseUrl}/approval/respond?id=${request.id}&action=reject&approver=${encodeURIComponent(approver)}`,
  viewUrl: `${baseUrl}/approval/view?id=${request.id}`
}));

return [{
  json: {
    ...request,
    approvalLinks,
    stored: true
  }
}];

// Split into individual notifications per approver
const request = $input.first().json;

return request.approvalLinks.map(link => ({
  json: {
    request,
    notification: {
      to: link.approver,
      subject: `[Action Required] ${request.subject}`,
      body: `
Approval Request: ${request.subject}

Requester: ${request.requester.name || request.requester.email}
Type: ${request.type}
Amount: ${request.amount ? '$' + request.amount : 'N/A'}
Priority: ${request.priority}
Level: ${request.currentLevel} of ${request.totalLevels}

Description:
${request.description}

Actions:
- Approve: ${link.approveUrl}
- Reject: ${link.rejectUrl}
- View Details: ${link.viewUrl}

This request will escalate if not responded to within ${request.timeoutMinutes} minutes.
      `.trim(),
      links: link
    }
  }
}));

// Compile response
const notifications = $input.all();
const request = notifications[0]?.json.request;

return [{
  json: {
    success: true,
    requestId: request.id,
    status: 'pending_approval',
    currentLevel: request.currentLevel,
    totalLevels: request.totalLevels,
    approvers: request.currentApprovers,
    expiresAt: new Date(Date.now() + request.timeoutMinutes * 60000).toISOString(),
    message: `Approval request created. ${request.currentApprovers.length} approver(s) notified.`
  }
}];

// Process approval response
const input = $input.first().json;
const query = input.query || {};
const staticData = $workflow.staticData;

const requestId = query.id;
const action = query.action;
const approver = query.approver;
const comment = query.comment || '';

if (!requestId || !action || !approver) {
  return [{
    json: {
      success: false,
      error: 'Missing required parameters: id, action, approver'
    }
  }];
}

// Get stored request
const request = staticData.approvals?.[requestId];

if (!request) {
  return [{
    json: {
      success: false,
      error: 'Approval request not found or expired'
    }
  }];
}

if (request.status !== 'pending') {
  return [{
    json: {
      success: false,
      error: `Request already ${request.status}`
    }
  }];
}

// Verify approver is authorized
if (!request.currentApprovers.includes(approver)) {
  return [{
    json: {
      success: false,
      error: 'You are not authorized to respond to this request'
    }
  }];
}

// Record the response
const response = {
  approver,
  action,
  comment,
  respondedAt: new Date().toISOString(),
  level: request.currentLevel
};

request.approvals.push(response);

if (action === 'reject') {
  request.status = 'rejected';
  request.rejectedBy = approver;
  request.rejectedAt = new Date().toISOString();
} else if (action === 'approve') {
  if (request.currentLevel >= request.totalLevels) {
    request.status = 'approved';
    request.approvedAt = new Date().toISOString();
  } else {
    request.currentLevel++;
    // Would trigger next level notifications here
  }
}

// Update stored request
staticData.approvals[requestId] = request;

return [{
  json: {
    success: true,
    requestId,
    action,
    newStatus: request.status,
    currentLevel: request.currentLevel,
    message: action === 'approve' 
      ? (request.status === 'approved' ? 'Request fully approved!' : `Approved at level ${request.currentLevel - 1}. Escalating to next level.`)
      : 'Request rejected.'
  }
}];

// Get approval status
const input = $input.first().json;
const query = input.query || {};
const staticData = $workflow.staticData;

const requestId = query.id;

if (!requestId) {
  // Return all pending approvals
  const pending = Object.values(staticData.approvals || {})
    .filter(r => r.status === 'pending');
  return [{
    json: {
      pending,
      count: pending.length
    }
  }];
}

const request = staticData.approvals?.[requestId];

if (!request) {
  return [{
    json: {
      success: false,
      error: 'Approval request not found'
    }
  }];
}

return [{
  json: {
    success: true,
    request: {
      id: request.id,
      type: request.type,
      subject: request.subject,
      status: request.status,
      requester: request.requester,
      currentLevel: request.currentLevel,
      totalLevels: request.totalLevels,
      approvals: request.approvals,
      createdAt: request.createdAt,
      expiresAt: request.expiresAt
    }
  }
}];
